UPDATE companies SET description='Oh Ghee Inc is based in Bend, Oregon. The company does not publicly disclose its founding year, ownership structure, or the names of its founders.

The business produces ghee—a clarified butter rendered from organic butter sourced from grass-fed cows—and extends that core ingredient into a line of skincare products, candles, and pet supplements. Manufacturing steps include butter clarification, blending with herbs for functional foods, formulation of topical creams, and candle pouring. No facility size, headcount, or production volumes are published.

Oh Ghee sells directly to consumers through its website, targeting shoppers interested in specialty cooking fats, natural skin care, home fragrance, and pet nutrition. The company does not list industrial or wholesale customers.

The brand positions its ghee as a nutrient-dense superfood rich in omega-3 and omega-9 fatty acids, vitamins A, D, E, and K, antioxidants, amino acids, minerals, and enzymes. It claims the fat is free of inflammatory properties, highly digestible, and serves as a delivery medium for fat-soluble herbs to create therapeutic benefits. Skincare products are marketed for deep hydration and relief from dryness, while the pet line is said to support joint health, coat shine, and digestion.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Ghee production (clarification of organic butter)", "Functional food formulation with fat-soluble herbs", "Skincare product formulation", "Candle manufacturing", "Pet supplement production"], "industries": ["Specialty food and beverage", "Natural skincare", "Pet care and nutrition", "Home fragrance"], "materials": ["Organic butter from grass-fed cows", "Ghee", "Fat-soluble herbs"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Ghee rendered from organic butter from grass-fed cows", "Nutrient-dense profile with omega-3, omega-9, vitamins A/D/E/K, antioxidants, amino acids, minerals, enzymes", "Free of inflammatory properties, highly digestible, serves as delivery medium for fat-soluble herbs", "Skincare formulated for deep hydration and relief from dry skin and irritation", "Pet supplement designed to lubricate joints, restore coat shine, support healthy digestion"], "facts_used": ["Headquarters in Bend, Oregon -> db", "Produces ghee from organic butter from grass-fed cows -> page \"/\"", "Offers skincare products, candles, and pet supplements -> page \"/\"", "Describes ghee as nutrient-dense superfood with omega-3, omega-9, vitamins A/D/E/K, antioxidants, amino acids, minerals, enzymes -> page \"/\"", "Claims ghee is free of inflammatory properties, highly digestible, and a delivery medium for fat-soluble herbs -> page \"/\"", "Markets skincare for deep hydration and relief from dryness -> page \"/\"", "Markets pet ghee for joint lubrication, coat shine, digestion support -> page \"/\"", "Sells directly to consumers via website -> page \"/\""], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "GHEE IS PURE BUTTERFAT RENDERED FROM ORGANIC BUTTER FROM GRASS-FED COWS.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='oh-ghee-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Ohana Fiber Mill operates in Honokaa on the Big Island of Hawaii. The business was founded by Alisha and Chris, who turned a love for the island into a venture that transforms local wool into sustainable fiber. No founding year is publicly stated.

The mill provides custom fiber processing from raw wool to finished skeins and produces its own 100% Hawaiian-grown and processed yarn blends. Those blends use Merino and Romney wool sourced from Kahua Ranch and other small local fiber producers. The facility is described as a cozy, historic space that also houses a retail store selling handmade items.

The company works directly with local wool producers, makers, farmers, and artists, building a regional network around Hawaiian fiber. Customers include individuals seeking custom processing services and buyers of the mill''s own yarn collections.

The founders frame the mill as a way to keep Hawaii''s fiber story alive, emphasizing connection to the land, the animals, and the community. The space is also intended as a gathering place for creativity and learning.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom fiber processing", "Wool-to-skein processing", "Yarn spinning and blending", "Handmade product fabrication"], "industries": ["Fiber arts", "Textile manufacturing", "Agriculture (wool production)", "Arts and crafts"], "materials": ["Merino wool", "Romney wool", "Hawaiian wool"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom fiber processing from customer-supplied wool", "100% Hawaiian-grown and processed yarn", "Yarn blends sourced from Kahua Ranch Merino and Romney wool", "Handmade items available in on-site retail store", "Mill serves as a community gathering place for fiber artists"], "facts_used": ["Headquarters: Honokaa, Hawaii -> db", "Founders: Alisha and Chris -> /about", "Custom fiber processing from customer-provided fiber -> /", "100% Hawaiian grown and processed yarn -> /", "Handmade items sold in retail store -> /", "Mill described as cozy, historic space -> /about", "Works closely with local wool producers -> /about", "Crafts yarn blends from Merino, Romney, and other fibers from Kahua Ranch -> /about", "Aims to keep Hawaii''s fiber story alive, connecting land, animals, and people -> /", "Offers a gathering place for makers, farmers, and artists -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We make quality fiber from local Hawaiian wool", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ohana-fiber-mill' AND approved AND profile IS NULL;
UPDATE companies SET description='Ohio Semitronics, Inc. is based in Hilliard, Ohio, and has been manufacturing electrical transducers and sensors since its founding in 1964. The company pioneered the first Hall Effect electrical measurement devices that year and has since served as a key resource for organizations such as Battelle Institute, Bell Labs, and the U.S. Department of Defense.

The company’s core business is custom electrical measurement devices, including a full line of standard transducers for AC/DC current, AC/DC voltage, watt-VAR, multifunction, frequency, power factor, signal conditioning, relays, switches, integrators, and panel meters.

Its customers span petroleum and petrochemical, electric utility, solar and wind energy, test and measurement, automation and control, and naval surface and subsurface applications. The firm has a track record with defense and industrial clients requiring high-accuracy sensors for critical environments.

Ohio Semitronics differentiates itself through a deep understanding of the inner workings of electrical measurements, enabling it to engineer sensors that achieve high accuracy, functionality, and durability in demanding application environments. The company emphasizes rapid prototyping throughput and an impeccable track record on challenging measurement projects.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom electrical measurement device engineering", "Hall Effect transducer design and manufacturing", "Standard transducer production (AC/DC current, AC/DC voltage, watt-VAR, multifunction, frequency, power factor)", "Signal conditioner manufacturing", "Relay/switch manufacturing", "Integrator manufacturing", "Panel meter manufacturing", "Rapid prototyping (2-6 weeks)", "CAD design", "3D printing for prototyping", "Accuracy calculation and specification assistance"], "industries": ["Petroleum and petrochemical", "Electric utility", "Solar energy", "Wind energy", "Test and measurement", "Automation and control", "Naval surface and subsurface", "Defense"], "materials": [], "equipment": [], "volume": "", "lead_time": "2-6 weeks for custom prototypes; 3 weeks typical for prototypes", "tolerances": "", "built_on": [], "facts_used": ["Company name and location: Hilliard, Ohio -> db", "Founded in 1964 -> /about", "Pioneered first Hall Effect electrical measurement devices in 1964 -> /about", "Key resource for Battelle Institute, Bell Labs, Department of Defense -> /about", "Core business: custom electrical measurements -> /about", "Standard transducers: AC/DC current, AC/DC voltage, watt-VAR, multifunction, frequency, power factor, signal conditioners, relays/switches, integrators, panel meters -> /", "Custom prototypes in 2-6 weeks, as fast as 3 weeks -> / and /about", "Uses CAD and 3D printing technologies -> /about", "Industries served: petroleum and petrochemical, electric utility, solar and wind, test and measurement, automation and control, naval surface and subsurface -> /about", "Deep understanding of electrical measurements for accuracy, functionality, durability -> /about", "Website: http://www.ohiosemitronics.com/ -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom electrical measurements are our core business", "founded_year": "1964", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ohio-semitronics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Ohio Woodworking Company operates from Cincinnati, Ohio, where it was founded in 1930 by William Frank, a German immigrant and cabinetmaker who started the business on the site of a former lumberyard. Now in its third generation of family ownership, the company is led by Tom Jr. and his brother-in-law Richard, who took over in 2005 after 75 years under the previous generation.

The shop produces custom millwork and cabinetry for commercial and institutional spaces, including bank fixtures, salon displays, university furniture, residential cabinetry, architectural millwork, and retail fixtures. Production blends CNC machining and AutoCAD drafting with traditional woodworking tools, allowing the team to handle one-of-a-kind builds as well as large-scale production runs from a facility near downtown Cincinnati with convenient access to I-71, I-75, and Route 562.

Clients span banking (notably U.S. Bank), salon, education, retail, medical, and residential sectors. The company collaborates directly with architects, designers, and trades to engineer fixtures and millwork packages that must be reproduced consistently across multiple locations.

Ohio Woodworking attributes its longevity to core values of quality, ingenuity, perseverance, humor, and family—principles the firm says are built into every project. The combination of nearly a century of experience with modern technology underpins its reputation for precision and on-time delivery.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom millwork", "Cabinetry", "Architectural millwork", "Retail fixture fabrication", "Bank fixture fabrication", "Salon furniture", "University furniture", "Residential cabinetry", "CNC machining", "AutoCAD drafting", "Traditional woodworking", "Design collaboration with architects/designers/trades", "Kitchen and food service stations", "Salon & Service Area Furniture"], "industries": ["Commercial", "Institutional", "Banking", "Salon", "Education", "Retail", "Residential", "Medical"], "materials": [], "equipment": ["CNC machinery", "AutoCAD drafting software"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Third-generation family-owned business", "Combines traditional woodworking with CNC machinery and AutoCAD drafting", "Decades-long partnerships with clients such as U.S. Bank", "Handles one-of-a-kind custom builds to large-scale production runs", "Facility near major highways (I-71, I-75, Route 562) for logistics"], "facts_used": ["Founded in 1930 by William Frank -> /about", "Third-generation family-owned -> /about, /", "Located in Cincinnati, Ohio -> /, /about", "Custom millwork and cabinetry for commercial/institutional spaces -> /", "Clients include U.S. Bank -> /", "Uses CNC machinery and AutoCAD drafting -> /about", "Handles one-of-a-kind to large-scale production -> /about", "Values: quality, ingenuity, perseverance, humor, family -> /about", "Facility near downtown Cincinnati, accessible via RT 562, I-75, I-71 -> /about", "Current leadership: Tom Jr. and Richard since 2005 -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "we combine nearly a ce